action.command:
cd /workspace/contracts && python3 << 'EOF'
import json
with open('openapi.contract.json') as f:
    c = json.load(f)

# Save a compact summary file for easier reading
out = {}
out['info'] = c.get('info')
out['servers'] = c.get('servers')
out['security'] = c.get('security')
out['x-websocket-endpoints'] = c.get('x-websocket-endpoints')
out['paths'] = {}
for p, methods in c['paths'].items():
    out['paths'][p] = {}
    for m, op in methods.items():
        if isinstance(op, dict):
            keys = ['operationId','summary','description','security','parameters','requestBody']
            responses = {}
            for code, r in op.get('responses', {}).items():
                if 'content' in r:
                    responses[code] = {k:v for k,v in r.items() if k in ('description', 'content')}
                else:
                    responses[code] = r
            out['paths'][p][m] = {k: op.get(k) for k in keys if k in op}
            out['paths'][p][m]['responses'] = responses

with open('/tmp/contract_compact.json', 'w') as f:
    json.dump(out, f, indent=2)
print('Saved compact contract to /tmp/contract_compact.json')
EOF
wc -l /tmp/contract_compact.json

