// ---------- AUDIT ----------

func (s *Store) AppendAudit(e domain.AuditEntry) error {
	if s.mongo != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		coll := s.mongo.Database("lab").Collection("audit")
		_, err := coll.InsertOne(ctx, bson.M{
			"id":            e.ID,
			"actorId":       e.ActorID,
			"actorUsername": e.ActorUsername,
			"role":          e.Role,
			"action":        e.Action,
			"entityType":    e.EntityType,
			"entityId":      e.EntityID,
			"outcome":       e.Outcome,
			"success":       e.Success,
			"changes":       e.Changes,
			"timestamp":     e.Timestamp,
		})
		return err
	}
	return nil
}

// helper

func mapToBSON(m map[string]interface{}) bson.M {
	out := bson.M{}
	for k, v := range m {
		out[k] = v
	}
	return out
}

