	}
	if req.FromLocationID == uuid.Nil || req.ToLocationID == uuid.Nil {
		WriteError(w, http.StatusBadRequest, "invalid_input", "from/to required")
		return
	}
	if req.ID == uuid.Nil {
		req.ID = uuid.New()
	}
	if req.Capacity.RegularUnits == 0 && req.Capacity.CooledUnits == 0 {
		req.Capacity.RegularUnits = 10
	}
	if err := s.st.CreateConnection(&req); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	s.audit(caller, "create_connection", "connection", req.ID.String(), true, "success", nil)
	s.svc.Recompute()
	s.st.AppendEvent("connection.created", map[string]interface{}{"id": req.ID.String()})
