func (s *Server) handleReadAssignment(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Query().Get("assignmentId")
	aid, err := uuid.Parse(idStr)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_id", "invalid assignmentId")
		return
	}
