func (s *Server) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	var req struct {
		AssignmentID uuid.UUID `json:"assignmentId"`
		Status       string    `json:"status"`
		Latitude     *float64  `json:"latitude,omitempty"`
		Longitude    *float64  `json:"longitude,omitempty"`
		Notes        string    `json:"notes"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	a, ok := s.st.GetAssignment(req.AssignmentID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != u.ID {
		WriteError(w, http.StatusForbidden, "forbidden", "not your assignment")
		return
	}
	now := time.Now()
	switch req.Status {
	case "in_progress":
		if a.StartedAt == nil {
			a.StartedAt = &now
		}
		a.Status = "in_progress"
	case "completed":
		a.Status = "completed"
		a.CompletedAt = &now
	default:
		a.Status = req.Status
	}
	if err := s.st.UpdateAssignment(a); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	if req.Latitude != nil && req.Longitude != nil {
		lat := *req.Latitude
		lng := *req.Longitude
		u.Latitude = &lat
		u.Longitude = &lng
		u.LastLocationUpdate = &now
		_ = s.st.UpdateUser(u)
	}
	s.audit(u, "update_assignment_progress", "assignment", a.ID.String(), true, "success", map[string]any{"status": req.Status, "notes": req.Notes})
	s.st.AppendEvent("assignment.progress", map[string]interface{}{"assignmentId": a.ID.String(), "status": req.Status})
	OK(w, a)
}

func (s *Server) handleCollectAndSeal(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	u := currentUser(r)
	if u == nil || !HasRole(u, "certified_collection_professional") {
		WriteError(w, http.StatusForbidden, "forbidden", "collector only")
		return
	}
	var req struct {
		SampleID       uuid.UUID `json:"sampleId"`
		AssignmentID   uuid.UUID `json:"assignmentId"`
		ContainerType  string    `json:"containerType"`
		TemperatureC   float64   `json:"temperatureC"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	smp, ok := s.st.GetSample(req.SampleID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	st, ok := s.st.GetSampleType(smp.SampleTypeID)
	if !ok {
		WriteError(w, http.StatusInternalServerError, "internal", "sample type gone")
		return
	}
	if st.QualifiedCollectorRequired {
		hasQ := false
		for _, q := range u.Qualifications {
			if q == st.Name {
				hasQ = true
				break
			}
		}
		if !hasQ {
			WriteError(w, http.StatusForbidden, "forbidden", "missing qualification")
			return
		}
	}
	if smp.Sealed {
		WriteError(w, http.StatusConflict, "conflict", "already sealed")
		return
	}
	now := time.Now()
	smp.Sealed = true
	smp.SealedAt = &now
	smp.CurrentHolderID = &u.ID
	smp.Status = "collected"
	if err := s.st.UpdateSample(smp); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	// Mark assignment in progress
	if req.AssignmentID != uuid.Nil {
		if a, ok := s.st.GetAssignment(req.AssignmentID); ok {
			a.Status = "in_progress"
			a.WorkerID = &u.ID
			if a.StartedAt == nil {
				a.StartedAt = &now
			}
			_ = s.st.UpdateAssignment(a)
		}
	}
	// Compatibility check
	if req.ContainerType != "" && req.ContainerType != st.ContainerType {
		smp.IsException = true
		smp.ExceptionReason = "container_mismatch"
		_ = s.st.UpdateSample(smp)
	}
	if req.TemperatureC != 0 && (req.TemperatureC < st.TemperatureMinC || req.TemperatureC > st.TemperatureMaxC) {
		smp.IsException = true
		if smp.ExceptionReason != "" {
			smp.ExceptionReason += ","
		}
		smp.ExceptionReason += "temperature_out_of_range"
		_ = s.st.UpdateSample(smp)
	}

	s.audit(u, "collect_and_seal", "sample", smp.ID.String(), true, "success", map[string]any{
		"containerType":  req.ContainerType,
		"temperatureC":   req.TemperatureC,
	})
	s.st.AppendEvent("sample.collected_and_sealed", map[string]interface{}{"sampleId": smp.ID.String(), "holderId": u.ID.String()})
	OK(w, smp)
}

func (s *Server) handleRegisterSealedSample(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	if !HasAnyRole(u, "certified_collection_professional", "relay_courier", "node_handler", "laboratory_intake_operator") {
		WriteError(w, http.StatusForbidden, "forbidden", "worker only")
		return
	}
	var req struct {
		SampleTypeID     uuid.UUID        `json:"sampleTypeId"`
		OriginType       string           `json:"originType"`
		OriginLocationID *uuid.UUID       `json:"originLocationId"`
		ContainerType    string           `json:"containerType"`
		TemperatureC     float64          `json:"temperatureC"`
		DeliveryDeadline time.Time        `json:"deliveryDeadline"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	if req.OriginType == "home" {
		WriteError(w, http.StatusBadRequest, "invalid_origin_type", "home cannot be pre-sealed")
		return
	}
	if req.OriginLocationID == nil {
		WriteError(w, http.StatusBadRequest, "invalid_input", "originLocationId required")
		return
	}
	st, ok := s.st.GetSampleType(req.SampleTypeID)
	if !ok {
		WriteError(w, http.StatusBadRequest, "invalid_input", "sample type not found")
		return
	}
	now := time.Now()
	smp := &domain.Sample{
		SampleTypeID: st.ID,
		Sealed:       true,
		Status:       "registered",
		SealedAt:     &now,
		CurrentHolderID: &u.ID,
		LastLocationID: req.OriginLocationID,
	}
	if err := s.st.CreateSample(smp); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save sample failed")
		return
	}
	creq := &domain.CollectionRequest{
		SampleID:              smp.ID,
		RequesterID:           u.ID,
		SampleTypeID:          st.ID,
		OriginType:            req.OriginType,
		OriginCoordinate:      domain.Coordinate{},
		OriginLocationID:      req.OriginLocationID,
		CollectionWindowStart: now,
		CollectionWindowEnd:   now,
		DeliveryDeadline:      req.DeliveryDeadline,
		Status:                "pending",
		AlreadySealed:         true,
	}
	if err := s.st.CreateRequest(creq); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save request failed")
		return
	}
	smp.RequestID = creq.ID
	_ = s.st.UpdateSample(smp)
	if req.ContainerType != "" && req.ContainerType != st.ContainerType {
		smp.IsException = true
		smp.ExceptionReason = "container_mismatch"
	}
	if req.TemperatureC != 0 && (req.TemperatureC < st.TemperatureMinC || req.TemperatureC > st.TemperatureMaxC) {
		smp.IsException = true
		if smp.ExceptionReason != "" {
			smp.ExceptionReason += ","
		}
		smp.ExceptionReason += "temperature_out_of_range"
	}
	_ = s.st.UpdateSample(smp)
	s.audit(u, "register_sealed_sample", "sample", smp.ID.String(), true, "success", map[string]any{"originType": req.OriginType})
	s.st.AppendEvent("sample.registered_sealed", map[string]interface{}{"sampleId": smp.ID.String()})
	Created(w, smp)
}

