	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	u := currentUser(r)
	if u == nil || !HasAnyRole(u, "administrator", "dispatcher") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin/dispatcher only")
		return
	}
	var req struct {
		JourneyID    uuid.UUID `json:"journeyId"`
		PlanVersion  int       `json:"planVersion"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	j, ok := s.st.GetJourney(req.JourneyID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if j.PlanVersion != req.PlanVersion {
