func (s *Server) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	if !HasAnyRole(u, "administrator", "dispatcher") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin/dispatcher only")
		return
	}
	entityType := r.URL.Query().Get("entityType")
	entityID := r.URL.Query().Get("entityId")
	actorID := r.URL.Query().Get("actorId")
	action := r.URL.Query().Get("action")
	limit := 200
	out := []domain.AuditEntry{}
	for _, e := range s.st.ListHandoffs() {
		_ = e
	}
	// Use mongo direct via store (placeholder; use mongo here)
	if s.st == nil {
		OK(w, out)
		return
	}
	// Use store in-memory by collecting? audit is in mongo; load from store
	// simpler: pull from store by scanning (not ideal) — instead expose events
	if limit > 1000 {
		limit = 1000
	}
	OK(w, s.auditFilter(entityType, entityID, actorID, action, limit))
}

// auditFilter queries the mongo collection for audit entries
func (s *Server) auditFilter(entityType, entityID, actorID, action string, limit int) []domain.AuditEntry {
	// we don't have direct mongo handle on server (kept in store). Use store method.
	// For now use in-memory events as audit fallback.
	out := []domain.AuditEntry{}
	// try mongo
	if s.st != nil && s.st.MongoHandle() != nil {
		coll := s.st.MongoHandle().Database("lab").Collection("audit")
		ctx, cancel := contextWithTimeout()
		defer cancel()
		filter := map[string]interface{}{}
		if entityType != "" {
			filter["entityType"] = entityType
		}
		if entityID != "" {
			filter["entityId"] = entityID
		}
		if actorID != "" {
			filter["actorId"] = actorID
		}
		if action != "" {
			filter["action"] = action
		}
		cur, err := coll.Find(ctx, filter)
		if err == nil {
			defer cur.Close(ctx)
			i := 0
			for cur.Next(ctx) {
				if i >= limit {
					break
				}
				var m map[string]interface{}
				if err := cur.Decode(&m); err == nil {
					out = append(out, mapToAudit(m))
				}
				i++
			}
		}
	}
	return out
}

func (s *Server) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	if !HasAnyRole(u, "administrator", "dispatcher") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin/dispatcher only")
		return
	}
	OK(w, map[string]any{
		"stats":                 s.st.Stats(),
		"locations":             s.st.ListLocations(),
		"connections":           s.st.ListConnections(),
		"assignments":           s.st.ListAssignments(),
		"samples":               s.st.AllSamples(),
		"requests":              s.st.ListRequests(),
		"journeys":              s.st.AllJourneys(),
		"users":                 s.st.AllUsers(),
		"sampleTypes":           s.st.AllSampleTypes(),
		"serviceability":        s.svc.Snapshot(),
		"disruptions":           s.st.ListDisruptions(),
	})
}

func (s *Server) handleListExceptions(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	if !HasAnyRole(u, "administrator", "dispatcher") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin/dispatcher only")
		return
	}
	out := []*domain.Sample{}
	for _, smp := range s.st.AllSamples() {
		if smp.IsException {
			out = append(out, smp)
		}
	}
	OK(w, out)
}

