	if s.mongo != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		coll := s.mongo.Database("lab").Collection("audit")
		_, err := coll.InsertOne(ctx, bson.M{
			"id":            e.ID,
			"actorId":       e.ActorID,
			"actorUsername": e.ActorUsername,
			"role":          e.Role,
			"action":        e.Action,
			"entityType":    e.EntityType,
			"entityId":      e.EntityID,
			"outcome":       e.Outcome,
			"success":       e.Success,
			"changes":       e.Changes,
			"timestamp":     e.Timestamp,
		})
		return err
	}
	return nil
}

