		var capJSON []byte
		if err := rows.Scan(&c.ID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes,
			&c.CostUnits, &c.Cooled, &c.Active, &capJSON); err != nil {
			return err
		}
		json.Unmarshal(capJSON, &c.Capacity)
		s.connections[c.ID] = c
	}
	return nil
}

// ---------- LAB ACCEPTANCES ----------

func (s *Store) UpsertAcceptance(a *domain.LabAcceptance) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if a.ID == uuid.Nil {
		a.ID = uuid.New()
	}
	// dedup by lab+sample
	for _, existing := range s.acceptances {
		if existing.LaboratoryID == a.LaboratoryID && existing.SampleTypeID == a.SampleTypeID {
			existing.Accepts = a.Accepts
			s.acceptances[existing.ID] = existing
			a.ID = existing.ID
			return s.persistAcceptance(existing)
		}
	}
	s.acceptances[a.ID] = a
	return s.persistAcceptance(a)
}

func (s *Store) GetAcceptance(labID, stID uuid.UUID) (*domain.LabAcceptance, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	for _, a := range s.acceptances {
		if a.LaboratoryID == labID && a.SampleTypeID == stID {
			return a, true
		}
	}
	return nil, false
}

func (s *Store) ListAcceptancesForLab(labID uuid.UUID) []*domain.LabAcceptance {
	s.mu.RLock()
	defer s.mu.RUnlock()
	out := []*domain.LabAcceptance{}
	for _, a := range s.acceptances {
		if a.LaboratoryID == labID {
			out = append(out, a)
		}
	}
	return out
}

func (s *Store) persistAcceptance(a *domain.LabAcceptance) error {
	if s.pg == nil {
		return nil
	}
	_, err := s.pg.Exec(context.Background(),
		`INSERT INTO lab_acceptances(id, laboratory_id, sample_type_id, accepts) VALUES ($1,$2,$3,$4)
		 ON CONFLICT (id) DO UPDATE SET accepts=EXCLUDED.accepts`,
		a.ID, a.LaboratoryID, a.SampleTypeID, a.Accepts)
	return err
}

func (s *Store) LoadAllAcceptances() error {
	if s.pg == nil {
		return nil
	}
	rows, err := s.pg.Query(context.Background(),
		`SELECT id, laboratory_id, sample_type_id, accepts FROM lab_acceptances`)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		a := &domain.LabAcceptance{}
		if err := rows.Scan(&a.ID, &a.LaboratoryID, &a.SampleTypeID, &a.Accepts); err != nil {
			return err
		}
		s.acceptances[a.ID] = a
	}
	return nil
}

// ---------- REQUESTS / SAMPLES / JOURNEYS ----------

func (s *Store) CreateRequest(r *domain.CollectionRequest) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if r.ID == uuid.Nil {
		r.ID = uuid.New()
	}
	r.CreatedAt = time.Now()
	s.requests[r.ID] = r
	return s.persistRequest(r)
}

func (s *Store) GetRequest(id uuid.UUID) (*domain.CollectionRequest, bool) {
