	var req domain.Location
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	if req.ID == uuid.Nil {
		WriteError(w, http.StatusBadRequest, "invalid_input", "id required")
		return
	}
	existing, ok := s.st.GetLocation(req.ID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "location not found")
		return
	}
	old := *existing
	*existing = req
	existing.IsLaboratory = req.Functions.Laboratory
	if err := s.st.UpdateLocation(existing); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	s.audit(caller, "update_location", "location", req.ID.String(), true, "success",
		map[string]any{"from": old, "to": *existing})
	s.svc.Recompute()
	s.st.AppendEvent("location.updated", map[string]interface{}{"id": req.ID.String(), "name": req.Name, "active": req.Active})
	OK(w, existing)
}

// ---------- Connections ----------

func (s *Server) handleListConnections(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	OK(w, s.st.ListConnections())
}

func (s *Server) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil || !HasRole(caller, "administrator") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin only")
		return
	}
	var req domain.Connection
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	if req.FromLocationID == uuid.Nil || req.ToLocationID == uuid.Nil {
		WriteError(w, http.StatusBadRequest, "invalid_input", "from/to required")
		return
	}
	if req.ID == uuid.Nil {
		req.ID = uuid.New()
	}
	if req.Capacity.RegularUnits == 0 && req.Capacity.CooledUnits == 0 {
		req.Capacity.RegularUnits = 10
	}
	if err := s.st.CreateConnection(&req); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	s.audit(caller, "create_connection", "connection", req.ID.String(), true, "success", nil)
	s.svc.Recompute()
	s.st.AppendEvent("connection.created", map[string]interface{}{"id": req.ID.String()})
	Created(w, req)
}

func (s *Server) handleUpdateConnection(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil || !HasRole(caller, "administrator") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin only")
