// ---------- Lab acceptances ----------

func (s *Server) handleListLabAcceptances(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	labIDStr := r.URL.Query().Get("laboratoryId")
	if labIDStr != "" {
		labID, err := uuid.Parse(labIDStr)
		if err != nil {
			WriteError(w, http.StatusBadRequest, "invalid_id", "invalid lab id")
			return
		}
		OK(w, s.st.ListAcceptancesForLab(labID))
		return
	}
	// Otherwise list all (admin/dispatcher only)
	if !HasAnyRole(u, "administrator", "dispatcher") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin/dispatcher only")
		return
	}
	out := []*domain.LabAcceptance{}
	for _, l := range s.st.AllLocations() {
		if l.IsLaboratory {
			out = append(out, s.st.ListAcceptancesForLab(l.ID)...)
		}
	}
	OK(w, out)
}

func (s *Server) handleUpsertLabAcceptance(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	var req domain.LabAcceptance
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	if req.LaboratoryID == uuid.Nil || req.SampleTypeID == uuid.Nil {
		WriteError(w, http.StatusBadRequest, "invalid_input", "lab and sample type required")
		return
	}
	// Authorization: laboratory intake operator assigned to this lab, or admin
	isLabOp := HasRole(caller, "laboratory_intake_operator") && caller.AssignedLaboratoryID != nil && *caller.AssignedLaboratoryID == req.LaboratoryID
	if !HasRole(caller, "administrator") && !isLabOp {
		WriteError(w, http.StatusForbidden, "forbidden", "admin or assigned lab operator only")
		return
	}
	lab, ok := s.st.GetLocation(req.LaboratoryID)
	if !ok || !lab.IsLaboratory {
		WriteError(w, http.StatusBadRequest, "invalid_input", "not a laboratory")
		return
	}
	if req.ID == uuid.Nil {
		req.ID = uuid.New()
	}
	if err := s.st.UpsertAcceptance(&req); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	s.audit(caller, "upsert_lab_acceptance", "lab", req.LaboratoryID.String(), true, "success",
		map[string]any{"sampleTypeId": req.SampleTypeID.String(), "accepts": req.Accepts})
	s.svc.Recompute()
	s.st.AppendEvent("lab.acceptance_changed", map[string]interface{}{"labId": req.LaboratoryID.String(), "sampleTypeId": req.SampleTypeID.String(), "accepts": req.Accepts})
	OK(w, req)
}

// ---------- Capacity ----------

func (s *Server) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	var req struct {
		ResourceType string    `json:"resourceType"`
		ResourceID   uuid.UUID `json:"resourceId"`
		RegularUnits *int      `json:"regularUnits,omitempty"`
		CooledUnits  *int      `json:"cooledUnits,omitempty"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	if req.ResourceType != "location" && req.ResourceType != "connection" {
		WriteError(w, http.StatusBadRequest, "invalid_input", "resourceType must be location or connection")
		return
	}

	var (
		ownerOK bool
		resourceName string
	)
	if req.ResourceType == "location" {
		l, ok := s.st.GetLocation(req.ResourceID)
		if !ok {
			WriteError(w, http.StatusNotFound, "not_found", "location not found")
			return
		}
		ownerOK = HasRole(caller, "administrator") ||
			(HasRole(caller, "node_handler") && caller.AssignedLocationID != nil && *caller.AssignedLocationID == req.ResourceID) ||
			(HasRole(caller, "laboratory_intake_operator") && caller.AssignedLaboratoryID != nil && *caller.AssignedLaboratoryID == req.ResourceID)
		if !ownerOK {
			WriteError(w, http.StatusForbidden, "forbidden", "not authorized for this location")
			return
		}
		resourceName = l.Name
		if req.RegularUnits != nil {
			if *req.RegularUnits < l.Capacity.RegularReserved {
				WriteError(w, http.StatusBadRequest, "invalid_input", "regular units below reserved")
				return
			}
			l.Capacity.RegularUnits = *req.RegularUnits
		}
		if req.CooledUnits != nil {
			if *req.CooledUnits < l.Capacity.CooledReserved {
				WriteError(w, http.StatusBadRequest, "invalid_input", "cooled units below reserved")
				return
			}
			l.Capacity.CooledUnits = *req.CooledUnits
		}
		if err := s.st.UpdateLocation(l); err != nil {
			WriteError(w, http.StatusInternalServerError, "internal", "save failed")
			return
		}
		s.audit(caller, "configure_capacity", "location", l.ID.String(), true, "success", map[string]any{"capacity": l.Capacity})
		s.st.AppendEvent("capacity.configured", map[string]interface{}{"resourceType": "location", "id": l.ID.String(), "regularUnits": l.Capacity.RegularUnits, "cooledUnits": l.Capacity.CooledUnits})
		OK(w, l)
		return
	}
	c, ok := s.st.GetConnection(req.ResourceID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "connection not found")
		return
	}
	if !HasRole(caller, "administrator") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin only for connection capacity")
		return
	}
	resourceName = "connection"
	if req.RegularUnits != nil {
		if *req.RegularUnits < c.Capacity.RegularReserved {
			WriteError(w, http.StatusBadRequest, "invalid_input", "regular units below reserved")
			return
		}
		c.Capacity.RegularUnits = *req.RegularUnits
	}
	if req.CooledUnits != nil {
		if *req.CooledUnits < c.Capacity.CooledReserved {
			WriteError(w, http.StatusBadRequest, "invalid_input", "cooled units below reserved")
			return
		}
		c.Capacity.CooledUnits = *req.CooledUnits
	}
	if err := s.st.UpdateConnection(c); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	s.audit(caller, "configure_capacity", "connection", c.ID.String(), true, "success", map[string]any{"capacity": c.Capacity})
	s.st.AppendEvent("capacity.configured", map[string]interface{}{"resourceType": "connection", "id": c.ID.String(), "regularUnits": c.Capacity.RegularUnits, "cooledUnits": c.Capacity.CooledUnits})
	OK(w, c)
	_ = resourceName
	_ = time.Now
}

