package api

import (
	"net/http"
	"time"

	"arena.local/lab/internal/domain"

	"github.com/google/uuid"
)

// ---------- Serviceability check ----------

func (s *Server) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	var req struct {
		Origin             domain.Coordinate `json:"origin"`
		OriginType         string            `json:"originType"`
		OriginNodeID       *uuid.UUID        `json:"originNodeId"`
		SampleTypeID       uuid.UUID         `json:"sampleTypeId"`
		RequestedAt        time.Time         `json:"requestedAt"`
		DeliveryDeadline   time.Time         `json:"deliveryDeadline"`
		EarliestCollection *time.Time        `json:"earliestCollectionAt"`
		LatestCollection   *time.Time        `json:"latestCollectionAt"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	if req.DeliveryDeadline.IsZero() {
		WriteError(w, http.StatusBadRequest, "invalid_deadline", "deadline required")
		return
	}
	if req.RequestedAt.IsZero() {
		req.RequestedAt = time.Now()
	}
	if req.OriginType == "" {
		req.OriginType = "home"
	}
	if req.OriginType != "home" && req.OriginType != "clinic" && req.OriginType != "node" {
		WriteError(w, http.StatusBadRequest, "invalid_origin_type", "invalid origin type")
		return
	}
	earliest := time.Now()
	latest := req.DeliveryDeadline
	if req.EarliestCollection != nil {
		earliest = *req.EarliestCollection
	}
	if req.LatestCollection != nil {
		latest = *req.LatestCollection
	}
	if !latest.After(earliest) {
		WriteError(w, http.StatusBadRequest, "invalid_collection_window", "latest must be after earliest")
		return
	}
	if !req.DeliveryDeadline.After(earliest) {
		WriteError(w, http.StatusBadRequest, "invalid_deadline", "deadline must be after collection window start")
		return
	}
	res := s.svc.Check(req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, req.DeliveryDeadline, &earliest, &latest)
	// Audit but do NOT create any resource
	s.audit(caller, "check_serviceability", "serviceability", "", res.Serviceable, res.Reason, map[string]any{
		"sampleTypeId": req.SampleTypeID.String(),
		"serviceable":  res.Serviceable,
		"reason":       res.Reason,
	})
	OK(w, res)
}

// ---------- Serviceability snapshot ----------

func (s *Server) handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	OK(w, s.svc.Snapshot())
}

// ---------- Create collection request ----------

func (s *Server) handleCreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil || !HasAnyRole(caller, "requester", "administrator", "dispatcher", "certified_collection_professional", "relay_courier", "node_handler", "laboratory_intake_operator") {
		WriteError(w, http.StatusForbidden, "forbidden", "no role permitted to create request")
		return
	}
	var req struct {
		SampleTypeID        uuid.UUID        `json:"sampleTypeId"`
		OriginType          string           `json:"originType"`
		OriginCoordinate    domain.Coordinate `json:"originCoordinate"`
		OriginLocationID    *uuid.UUID       `json:"originLocationId"`
		OriginHomeAddress   string           `json:"originHomeAddress"`
		CollectionWindowStart time.Time      `json:"earliestCollectionAt"`
		CollectionWindowEnd   time.Time      `json:"latestCollectionAt"`
		DeliveryDeadline    time.Time        `json:"deliveryDeadline"`
		AlreadySealed       bool             `json:"alreadySealed"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	if req.SampleTypeID == uuid.Nil {
		WriteError(w, http.StatusBadRequest, "invalid_input", "sampleTypeId required")
		return
	}
	if _, ok := s.st.GetSampleType(req.SampleTypeID); !ok {
		WriteError(w, http.StatusBadRequest, "invalid_input", "unknown sampleType")
		return
	}
	if req.OriginType == "" {
		req.OriginType = "home"
	}
	if req.AlreadySealed && req.OriginType == "home" {
		WriteError(w, http.StatusBadRequest, "invalid_origin_type", "home cannot be pre-sealed")
		return
	}
	if !req.CollectionWindowEnd.After(req.CollectionWindowStart) {
		WriteError(w, http.StatusBadRequest, "invalid_collection_window", "invalid window")
		return
	}
	if !req.DeliveryDeadline.After(req.CollectionWindowEnd) {
		WriteError(w, http.StatusBadRequest, "invalid_deadline", "deadline must be after window end")
		return
	}
	if req.DeliveryDeadline.Before(time.Now()) {
		WriteError(w, http.StatusBadRequest, "invalid_deadline", "deadline in past")
		return
	}

	// Re-check serviceability
	res := s.svc.Check(req.OriginCoordinate, req.OriginType, req.OriginLocationID, req.SampleTypeID, req.DeliveryDeadline, &req.CollectionWindowStart, &req.CollectionWindowEnd)
	if !res.Serviceable {
		// Still create a request in unserviceable state? No — contract says reject on no serviceability.
		WriteError(w, http.StatusBadRequest, "not_serviceable", "Serviceability check failed: "+res.Reason)
		return
	}

	// Create sample
	sample := &domain.Sample{
		RequestID:    uuid.Nil,
		SampleTypeID: req.SampleTypeID,
		Sealed:       req.AlreadySealed,
		Status:       "registered",
	}
	if req.AlreadySealed {
		now := time.Now()
		sample.SealedAt = &now
	}
	if err := s.st.CreateSample(sample); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "create sample failed")
		return
	}

	// Create request
	creq := &domain.CollectionRequest{
		SampleID:              sample.ID,
		RequesterID:           caller.ID,
		SampleTypeID:          req.SampleTypeID,
		OriginType:            req.OriginType,
		OriginCoordinate:      req.OriginCoordinate,
		OriginLocationID:      req.OriginLocationID,
		OriginHomeAddress:     req.OriginHomeAddress,
		CollectionWindowStart: req.CollectionWindowStart,
		CollectionWindowEnd:   req.CollectionWindowEnd,
		DeliveryDeadline:      req.DeliveryDeadline,
		Status:                "pending",
		Serviceability:        "serviceable",
		AlreadySealed:         req.AlreadySealed,
	}
	if err := s.st.CreateRequest(creq); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "create request failed")
		return
	}
	sample.RequestID = creq.ID
	_ = s.st.UpdateSample(sample)

	// Plan journey
	if err := s.planJourney(creq, sample); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "plan journey failed: "+err.Error())
		return
	}

	s.audit(caller, "create_collection_request", "request", creq.ID.String(), true, "success", map[string]any{
		"sampleType": req.SampleTypeID.String(),
	})
	s.st.AppendEvent("request.created", map[string]interface{}{"requestId": creq.ID.String(), "sampleId": sample.ID.String()})

	Created(w, map[string]any{
		"request":                creq,
		"sample":                 sample,
		"serviceability":         res,
	})
}

func (s *Server) planJourney(creq *domain.CollectionRequest, sample *domain.Sample) error {
	// Build simple route: origin → nearest collection point → hub → lab
	locations := s.st.AllLocations()
	var fromLoc *domain.Location
	if creq.OriginType == "node" || creq.OriginType == "clinic" {
		if creq.OriginLocationID != nil {
			l, ok := s.st.GetLocation(*creq.OriginLocationID)
			if ok {
				fromLoc = l
			}
		}
	}
	if fromLoc == nil {
		// pick nearest active collection point
		var bestDist = 1e18
		for _, l := range locations {
			if l.Active && l.Functions.CollectionPoint {
				dx := l.Latitude - creq.OriginCoordinate.Latitude
				dy := l.Longitude - creq.OriginCoordinate.Longitude
				d := dx*dx + dy*dy
				if d < bestDist {
					bestDist = d
					fromLoc = l
				}
			}
		}
	}
	if fromLoc == nil {
		return nil
	}

	// Accepting lab
	var lab *domain.Location
	for _, l := range locations {
		if l.IsLaboratory && l.Active && l.Functions.Laboratory {
			if acc, ok := s.st.GetAcceptance(l.ID, creq.SampleTypeID); ok && acc.Accepts {
				lab = l
				break
			}
		}
	}
	if lab == nil {
		return nil
	}

	// Find hub between
	var hub *domain.Location
	for _, l := range locations {
		if l.Functions.Hub && l.Active {
			hub = l
			break
		}
	}

	// Build stops
	stops := []domain.JourneyStop{
		{Sequence: 0, LocationID: fromLoc.ID, LocationName: fromLoc.Name, Latitude: fromLoc.Latitude, Longitude: fromLoc.Longitude, Function: "pickup"},
	}
	if hub != nil && hub.ID != fromLoc.ID && hub.ID != lab.ID {
		stops = append(stops, domain.JourneyStop{Sequence: 1, LocationID: hub.ID, LocationName: hub.Name, Latitude: hub.Latitude, Longitude: hub.Longitude, Function: "transfer"})
	}
	stopLab := len(stops)
	stops = append(stops, domain.JourneyStop{Sequence: stopLab, LocationID: lab.ID, LocationName: lab.Name, Latitude: lab.Latitude, Longitude: lab.Longitude, Function: "laboratory"})

	// Estimate ETAs
	tNow := time.Now()
	stops[0].DepartureETA = &tNow
	for i := 1; i < len(stops); i++ {
		eta := tNow.Add(time.Duration(i*15) * time.Minute)
		stops[i].ArrivalETA = &eta
	}
	eta := tNow.Add(time.Duration(len(stops)*15+5) * time.Minute)
	est := eta

	// Create assignments for each leg
	journey := &domain.JourneyPlan{
		RequestID:           creq.ID,
		SampleIDs:           []uuid.UUID{sample.ID},
		Status:              "active",
		Stops:               stops,
		EstimatedCompletion: &est,
	}
	if err := s.st.CreateJourney(journey); err != nil {
		return err
	}

	// First leg: collection (certified professional)
	leg1 := &domain.Assignment{
		JourneyID:      journey.ID,
		WorkerRole:     "certified_collection_professional",
		FromLocationID: fromLoc.ID,
		ToLocationID:   hubIfAny(fromLoc, hub, lab).ID,
		Mode:           "collection",
		Status:         "pending",
	}
	if err := s.st.CreateAssignment(leg1); err != nil {
		return err
	}
	// second leg: relay courier
	mid := hubIfAny(fromLoc, hub, lab)
	if mid.ID != lab.ID {
		leg2 := &domain.Assignment{
			JourneyID:      journey.ID,
			WorkerRole:     "relay_courier",
			FromLocationID: mid.ID,
			ToLocationID:   lab.ID,
			Mode:           "transport",
			Status:         "pending",
		}
		if err := s.st.CreateAssignment(leg2); err != nil {
			return err
		}
		// Final leg: lab intake
		leg3 := &domain.Assignment{
			JourneyID:      journey.ID,
			WorkerRole:     "laboratory_intake_operator",
			FromLocationID: lab.ID,
			ToLocationID:   lab.ID,
			Mode:           "intake",
			Status:         "pending",
		}
		if err := s.st.CreateAssignment(leg3); err != nil {
			return err
		}
	} else {
		// Direct leg
		leg2 := &domain.Assignment{
			JourneyID:      journey.ID,
			WorkerRole:     "relay_courier",
			FromLocationID: fromLoc.ID,
			ToLocationID:   lab.ID,
			Mode:           "transport",
			Status:         "pending",
		}
		if err := s.st.CreateAssignment(leg2); err != nil {
			return err
		}
	}

	// Reserve capacity
	locCap := *fromLoc
	if fromLoc.Capacity.RegularUnits > 0 {
		locCap.Capacity.RegularReserved++
		_ = s.st.UpdateLocation(fromLoc)
		s.st.AddReservation(&domain.CapacityReservation{
			ResourceType: "location",
			ResourceID:   fromLoc.ID,
			JourneyID:    journey.ID,
			SampleID:     sample.ID,
			PlanVersion:  1,
			RegularUnits: 1,
		})
	}

	// Sample holder: registered to requester
	cID := creq.RequesterID
	sample.CurrentHolderID = &cID
	sample.LastLocationID = &fromLoc.ID
	coord := creq.OriginCoordinate
	sample.LastCoordinate = &coord
	sample.Status = "awaiting_collection"
	_ = s.st.UpdateSample(sample)

	return nil
}

func callerID(creq *domain.CollectionRequest) uuid.UUID {
	return creq.RequesterID
}

func hubIfAny(from, hub, lab *domain.Location) *domain.Location {
	if hub != nil && hub.ID != from.ID && hub.ID != lab.ID {
		return hub
	}
	return lab
}

