func (s *Server) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	var req struct {
		AssignmentID uuid.UUID `json:"assignmentId"`
		IdempotencyKey string  `json:"idempotencyKey"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	a, ok := s.st.GetAssignment(req.AssignmentID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != u.ID {
		WriteError(w, http.StatusForbidden, "forbidden", "assignment not offered to you")
		return
	}
	if a.Status == "completed" {
		OK(w, a)
		return
	}
	if a.Status != "offered" && a.Status != "pending" && a.Status != "accepted" {
		WriteError(w, http.StatusConflict, "conflict", "assignment not available")
		return
	}
	now := time.Now()
	a.AcceptedAt = &now
	a.Status = "accepted"
	if err := s.st.UpdateAssignment(a); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	// Update sample holder
	for _, smp := range s.st.AllSamples() {
		j, ok := s.st.GetJourney(a.JourneyID)
		if !ok {
			continue
		}
		for _, sid := range j.SampleIDs {
			if sid == smp.ID {
				smp.CurrentHolderID = &u.ID
				smp.LastLocationID = &a.FromLocationID
				smp.Status = "in_transit"
				_ = s.st.UpdateSample(smp)
			}
		}
		_ = j
	}
	s.audit(u, "accept_assignment", "assignment", a.ID.String(), true, "success", nil)
	s.st.AppendEvent("assignment.accepted", map[string]interface{}{"assignmentId": a.ID.String(), "workerId": u.ID.String()})
	OK(w, a)
}

