func (s *Server) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	var req struct {
		HandoffID uuid.UUID `json:"handoffId"`
		Side      string    `json:"side"` // "sender" or "receiver"
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	h, ok := s.st.GetHandoff(req.HandoffID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "handoff not found")
		return
	}
	now := time.Now()
	switch req.Side {
	case "sender":
		if h.SenderID != u.ID {
			WriteError(w, http.StatusForbidden, "forbidden", "not sender")
			return
		}
		h.SenderConfirmed = true
		h.SenderConfirmedAt = &now
	case "receiver":
		if h.ReceiverID != u.ID {
			WriteError(w, http.StatusForbidden, "forbidden", "not receiver")
			return
		}
		h.ReceiverConfirmed = true
		h.ReceiverConfirmedAt = &now
	default:
		WriteError(w, http.StatusBadRequest, "invalid_input", "side must be sender or receiver")
		return
	}
	if h.SenderConfirmed && h.ReceiverConfirmed {
		h.Status = "completed"
		h.CompletedAt = &now
		// transfer custody
		if smp, ok := s.st.GetSample(h.SampleID); ok {
			smp.CurrentHolderID = &h.ReceiverID
			smp.Status = "in_transit"
			_ = s.st.UpdateSample(smp)
		}
	}
	if err := s.st.UpdateHandoff(h); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	s.audit(u, "confirm_handoff", "handoff", h.ID.String(), true, "success", map[string]any{"side": req.Side})
	s.st.AppendEvent("handoff.confirmed", map[string]interface{}{"handoffId": h.ID.String(), "side": req.Side, "status": h.Status})
	OK(w, h)
}

func (s *Server) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	u := currentUser(r)
	if u == nil || !HasRole(u, "laboratory_intake_operator") {
		WriteError(w, http.StatusForbidden, "forbidden", "lab operator only")
		return
	}
	var req struct {
		SampleID     uuid.UUID `json:"sampleId"`
		AssignmentID uuid.UUID `json:"assignmentId"`
		Exception    bool      `json:"exception"`
		ExceptionReason string `json:"exceptionReason"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	smp, ok := s.st.GetSample(req.SampleID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	now := time.Now()
	smp.DeliveredAt = &now
	smp.Status = "received"
	smp.CurrentHolderID = &u.ID
	if req.Exception {
		smp.IsException = true
		smp.ExceptionReason = req.ExceptionReason
	}
	_ = s.st.UpdateSample(smp)
	if req.AssignmentID != uuid.Nil {
		if a, ok := s.st.GetAssignment(req.AssignmentID); ok {
			a.Status = "completed"
			a.CompletedAt = &now
			_ = s.st.UpdateAssignment(a)
		}
	}
	// release reservation
	for _, r := range s.st.ListReservationsByJourney(smp.RequestID) {
		if r.SampleID == smp.ID {
			_ = s.st.DeleteReservation(r.ID)
		}
	}
	s.audit(u, "confirm_laboratory_receipt", "sample", smp.ID.String(), true, "success", map[string]any{"exception": req.Exception})
	s.st.AppendEvent("sample.received", map[string]interface{}{"sampleId": smp.ID.String(), "labOperatorId": u.ID.String()})
	OK(w, smp)
}

