package api

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"net/http"
	"strings"
	"sync"
	"time"

	"arena.local/lab/internal/auth"
	"arena.local/lab/internal/domain"
	"arena.local/lab/internal/realtime"
	"arena.local/lab/internal/serviceability"
	"arena.local/lab/internal/store"

	"github.com/google/uuid"
	"github.com/gorilla/websocket"
	"github.com/redis/go-redis/v9"
)

type Server struct {
	mu    sync.Mutex
	st    *store.Store
	rdb   *redis.Client
	svc   *serviceability.Serviceability
	hub   *realtime.Hub
	mux   *http.ServeMux
	jwtSecret []byte
	upgrader  websocket.Upgrader
	startTime time.Time
}

func NewServer(st *store.Store, rdb *redis.Client, svc *serviceability.Serviceability) *Server {
	s := &Server{
		st:        st,
		rdb:       rdb,
		svc:       svc,
		hub:       realtime.NewHub(),
		mux:       http.NewServeMux(),
		jwtSecret: []byte("dev-secret-rotate-in-prod"),
		upgrader:  websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }},
		startTime: time.Now(),
	}
	s.routes()
	return s
}

func (s *Server) routes() {
	// Health & ready
	s.mux.HandleFunc("/ready", s.handleReady)
	s.mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.Write([]byte(`{"status":"ok"}`))
	})

	// Static & frontend
	s.mux.Handle("/", http.FileServer(http.Dir("/workspace/app-setup/static")))

	// WebSocket events
	s.mux.HandleFunc("/api/events", s.handleEvents)

	// API
	s.mux.HandleFunc("/api/login", s.handleLogin)
	s.mux.HandleFunc("/api/logout", s.handleLogout)
	s.mux.HandleFunc("/api/select-active-role", s.handleSelectActiveRole)
	s.mux.HandleFunc("/api/read-user", s.handleReadUser)
	s.mux.HandleFunc("/api/list-users", s.handleListUsers)
	s.mux.HandleFunc("/api/create-user", s.handleCreateUser)
	s.mux.HandleFunc("/api/update-user-access", s.handleUpdateUserAccess)
	s.mux.HandleFunc("/api/update-user-roles", s.handleUpdateUserRoles)
	s.mux.HandleFunc("/api/update-user-location", s.handleUpdateUserLocation)
	s.mux.HandleFunc("/api/update-user-certifications", s.handleUpdateUserCertifications)
	s.mux.HandleFunc("/api/list-certifications", s.handleListCertifications)
	s.mux.HandleFunc("/api/issue-certification", s.handleIssueCertification)

	// Sample types
	s.mux.HandleFunc("/api/list-sample-types", s.handleListSampleTypes)
	s.mux.HandleFunc("/api/create-sample-type", s.handleCreateSampleType)
	s.mux.HandleFunc("/api/update-sample-type", s.handleUpdateSampleType)

	// Locations & connections
	s.mux.HandleFunc("/api/list-locations", s.handleListLocations)
	s.mux.HandleFunc("/api/read-location", s.handleReadLocation)
	s.mux.HandleFunc("/api/create-location", s.handleCreateLocation)
	s.mux.HandleFunc("/api/update-location", s.handleUpdateLocation)
	s.mux.HandleFunc("/api/list-connections", s.handleListConnections)
	s.mux.HandleFunc("/api/create-connection", s.handleCreateConnection)
	s.mux.HandleFunc("/api/update-connection", s.handleUpdateConnection)

	// Lab acceptances
	s.mux.HandleFunc("/api/list-lab-acceptances", s.handleListLabAcceptances)
	s.mux.HandleFunc("/api/upsert-lab-acceptance", s.handleUpsertLabAcceptance)

	// Capacity
	s.mux.HandleFunc("/api/configure-capacity", s.handleConfigureCapacity)

	// Requests & samples
	s.mux.HandleFunc("/api/check-serviceability", s.handleCheckServiceability)
	s.mux.HandleFunc("/api/create-collection-request", s.handleCreateCollectionRequest)
	s.mux.HandleFunc("/api/list-requests", s.handleListRequests)
	s.mux.HandleFunc("/api/read-request", s.handleReadRequest)

	// Serviceability snapshot
	s.mux.HandleFunc("/api/read-serviceability-snapshot", s.handleReadServiceabilitySnapshot)

	// Work & assignments
	s.mux.HandleFunc("/api/list-role-work", s.handleListRoleWork)
	s.mux.HandleFunc("/api/list-assignments", s.handleListAssignments)
	s.mux.HandleFunc("/api/read-assignment", s.handleReadAssignment)
	s.mux.HandleFunc("/api/accept-assignment", s.handleAcceptAssignment)
	s.mux.HandleFunc("/api/decline-assignment", s.handleDeclineAssignment)

	// Workers
	s.mux.HandleFunc("/api/set-worker-availability", s.handleSetWorkerAvailability)
	s.mux.HandleFunc("/api/record-worker-location", s.handleRecordWorkerLocation)
	s.mux.HandleFunc("/api/update-assignment-progress", s.handleUpdateAssignmentProgress)

	// Collection & handoffs
	s.mux.HandleFunc("/api/collect-and-seal", s.handleCollectAndSeal)
	s.mux.HandleFunc("/api/initiate-handoff", s.handleInitiateHandoff)
	s.mux.HandleFunc("/api/confirm-handoff", s.handleConfirmHandoff)
	s.mux.HandleFunc("/api/confirm-laboratory-receipt", s.handleConfirmLaboratoryReceipt)
	s.mux.HandleFunc("/api/register-sealed-sample", s.handleRegisterSealedSample)
	s.mux.HandleFunc("/api/record-handling-checkpoint", s.handleRecordHandlingCheckpoint)

	// Journeys
	s.mux.HandleFunc("/api/read-journey-plan", s.handleReadJourneyPlan)
	s.mux.HandleFunc("/api/replan-journey", s.handleReplanJourney)

	// Disruptions
	s.mux.HandleFunc("/api/report-disruption", s.handleReportDisruption)

	// Audit
	s.mux.HandleFunc("/api/search-audit-trail", s.handleSearchAuditTrail)

	// Operations state
	s.mux.HandleFunc("/api/read-operations-state", s.handleReadOperationsState)

	// Exceptions
	s.mux.HandleFunc("/api/list-exceptions", s.handleListExceptions)
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, Idempotency-Key")
	w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS, PATCH")
	if r.Method == http.MethodOptions {
		w.WriteHeader(http.StatusNoContent)
		return
	}
	s.mux.ServeHTTP(w, r)
}

// ---------- Error helper ----------

func WriteError(w http.ResponseWriter, status int, code, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]any{"error": msg, "code": code})
}

func WriteJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// ---------- Auth helpers ----------

type ctxKey int

const userKey ctxKey = 0

func (s *Server) authenticate(r *http.Request) (*domain.User, error) {
	tok, err := auth.ParseBearer(r.Header.Get("Authorization"))
	if err != nil {
		return nil, err
	}
	uid, ok := s.st.GetSession(tok)
	if !ok {
		return nil, errors.New("invalid token")
	}
	u, ok := s.st.GetUser(uid)
	if !ok {
		return nil, errors.New("user gone")
	}
	return u, nil
}

func (s *Server) requireAuth(fn http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		u, err := s.authenticate(r)
		if err != nil {
			WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
			return
		}
		ctx := context.WithValue(r.Context(), userKey, u)
		fn(w, r.WithContext(ctx))
	}
}

func currentUser(r *http.Request) *domain.User {
	u, _ := r.Context().Value(userKey).(*domain.User)
	return u
}

// ---------- Ready ----------

func (s *Server) handleReady(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	// Verify datastores
	ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
	defer cancel()
	ok := true
	if s.rdb != nil {
		if err := s.rdb.Ping(ctx).Err(); err != nil {
			ok = false
		}
	}
	if ok {
		w.WriteHeader(http.StatusOK)
		w.Write([]byte(`{"status":"ready"}`))
	} else {
		w.WriteHeader(http.StatusServiceUnavailable)
		w.Write([]byte(`{"status":"unready"}`))
	}
}

// ---------- Events (WebSocket) ----------

func (s *Server) handleEvents(w http.ResponseWriter, r *http.Request) {
	c, err := s.upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	// Optional auth: token can be passed via query
	var uid uuid.UUID
	if tok := r.URL.Query().Get("token"); tok != "" {
		if u, ok := s.st.GetSession(tok); ok {
			uid = u
		}
	}
	client := &realtime.Client{
		UserID: uid.String(),
		Conn:   c,
		Send:   make(chan []byte, 256),
	}
	s.hub.Add(client)
	defer s.hub.Remove(client)

	// Send existing events from cursor
	cursorStr := r.URL.Query().Get("cursor")
	var cursor int64
	fmt.Sscanf(cursorStr, "%d", &cursor)
	events, maxID := s.st.GetEventsSince(cursor)
	for _, ev := range events {
		b, _ := json.Marshal(ev)
		c.WriteMessage(websocket.TextMessage, b)
	}
	cursor = maxID

	// Reader loop
	go func() {
		for {
			_, _, err := c.ReadMessage()
			if err != nil {
				return
			}
		}
	}()

	// Writer loop
	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case msg, ok := <-client.Send:
			if !ok {
				return
			}
			if err := c.WriteMessage(websocket.TextMessage, msg); err != nil {
				return
			}
		case <-ticker.C:
			// Heartbeat
