	if len(req.Roles) == 0 {
		WriteError(w, http.StatusBadRequest, "invalid_input", "at least one role required")
		return
	}
	if _, exists := s.st.GetUserByName(req.Username); exists {
		WriteError(w, http.StatusConflict, "conflict", "username exists")
		return
	}
	salt := randomSalt()
	u := &domain.User{
		ID:          uuid.New(),
		Username:    req.Username,
		Email:       req.Email,
		FullName:    req.FullName,
		Phone:       req.Phone,
		Roles:       req.Roles,
		Active:      true,
		PasswordHash: auth.HashPassword(req.Password, salt),
		AssignedLocationID:   req.AssignedLocationID,
		AssignedLaboratoryID: req.AssignedLaboratoryID,
		Available:  true,
		ActiveRole: req.Roles[0],
	}
	if err := s.st.CreateUser(u); err != nil {
		WriteError(w, http.StatusConflict, "conflict", err.Error())
		return
	}
	s.audit(caller, "create_user", "user", u.ID.String(), true, "success", map[string]any{"username": u.Username, "roles": u.Roles})
	s.st.AppendEvent("user.created", map[string]interface{}{"userId": u.ID.String(), "username": u.Username})
	Created(w, u)
}

func randomSalt() string {
	b := make([]byte, 8)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func (s *Server) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil || !HasRole(caller, "administrator") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin only")
		return
	}
	var req struct {
		UserID  string `json:"userId"`
		Active  *bool  `json:"active"`
		Password string `json:"password"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	uid, err := uuid.Parse(req.UserID)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_id", "invalid userId")
		return
	}
	u, ok := s.st.GetUser(uid)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "user not found")
		return
	}
	if req.Active != nil {
		u.Active = *req.Active
	}
	if req.Password != "" {
		u.PasswordHash = auth.HashPassword(req.Password, u.Username)
	}
	if err := s.st.UpdateUser(u); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	s.audit(caller, "update_user_access", "user", u.ID.String(), true, "success", map[string]any{"active": u.Active})
	OK(w, u)
}

func (s *Server) handleUpdateUserRoles(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil || !HasRole(caller, "administrator") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin only")
		return
	}
	var req struct {
		UserID string   `json:"userId"`
		Roles  []string `json:"roles"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	uid, err := uuid.Parse(req.UserID)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_id", "invalid userId")
		return
	}
	u, ok := s.st.GetUser(uid)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "user not found")
		return
	}
	oldRoles := u.Roles
	u.Roles = req.Roles
	if u.ActiveRole == "" || !HasRole(u, u.ActiveRole) {
		u.ActiveRole = ""
		if len(u.Roles) > 0 {
			u.ActiveRole = u.Roles[0]
		}
	}
	if err := s.st.UpdateUser(u); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	s.audit(caller, "update_user_roles", "user", u.ID.String(), true, "success", map[string]any{"from": oldRoles, "to": u.Roles})
	OK(w, u)
}

func (s *Server) handleUpdateUserLocation(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	var req struct {
		UserID    string  `json:"userId"`
		Latitude  float64 `json:"latitude"`
		Longitude float64 `json:"longitude"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	target := u
	if req.UserID != "" {
		uid, err := uuid.Parse(req.UserID)
		if err != nil {
			WriteError(w, http.StatusBadRequest, "invalid_id", "invalid userId")
			return
		}
		if uid != u.ID && !HasAnyRole(u, "administrator", "dispatcher") {
			WriteError(w, http.StatusForbidden, "forbidden", "cannot update other user")
			return
		}
		t, ok := s.st.GetUser(uid)
		if !ok {
			WriteError(w, http.StatusNotFound, "not_found", "user not found")
			return
		}
		target = t
	}
	lat := req.Latitude
	lng := req.Longitude
	target.Latitude = &lat
	target.Longitude = &lng
	now := time.Now()
	target.LastLocationUpdate = &now
	if err := s.st.UpdateUser(target); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	s.audit(u, "update_user_location", "user", target.ID.String(), true, "success", map[string]any{"latitude": lat, "longitude": lng})
	s.st.AppendEvent("user.location_updated", map[string]interface{}{"userId": target.ID.String(), "latitude": lat, "longitude": lng})
	OK(w, target)
}

func (s *Server) handleUpdateUserCertifications(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil || !HasRole(caller, "administrator") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin only")
		return
	}
	var req struct {
		UserID         string    `json:"userId"`
		Certifications []struct {
			SampleTypeID  uuid.UUID `json:"sampleTypeId"`
			SampleTypeName string    `json:"sampleTypeName"`
			ExpiresAt      *time.Time `json:"expiresAt,omitempty"`
		} `json:"certifications"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	uid, err := uuid.Parse(req.UserID)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_id", "invalid userId")
		return
	}
	u, ok := s.st.GetUser(uid)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "user not found")
		return
	}
	u.Certifications = nil
	u.Qualifications = nil
	for _, c := range req.Certifications {
		st, ok := s.st.GetSampleType(c.SampleTypeID)
		nm := c.SampleTypeName
		if ok {
			nm = st.Name
		}
		u.Certifications = append(u.Certifications, domain.Certification{
			UserID:         u.ID,
			SampleTypeID:   c.SampleTypeID,
			SampleTypeName: nm,
			IssuedAt:       time.Now(),
			ExpiresAt:      c.ExpiresAt,
		})
		u.Qualifications = append(u.Qualifications, nm)
	}
	if err := s.st.UpdateUser(u); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	s.audit(caller, "update_user_certifications", "user", u.ID.String(), true, "success", map[string]any{"count": len(u.Certifications)})
	OK(w, u)
}

func (s *Server) handleListCertifications(w http.ResponseWriter, r *http.Request) {
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "auth required")
		return
	}
	OK(w, u.Certifications)
}

func (s *Server) handleIssueCertification(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "POST required")
		return
	}
	caller := currentUser(r)
	if caller == nil || !HasRole(caller, "administrator") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin only")
		return
	}
	var req struct {
		UserID       string     `json:"userId"`
		SampleTypeID uuid.UUID  `json:"sampleTypeId"`
		ExpiresAt    *time.Time `json:"expiresAt,omitempty"`
	}
	if err := ReadJSON(r, &req); err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "invalid JSON")
		return
	}
	uid, err := uuid.Parse(req.UserID)
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_id", "invalid userId")
		return
	}
	u, ok := s.st.GetUser(uid)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "user not found")
		return
	}
	st, ok := s.st.GetSampleType(req.SampleTypeID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "sample type not found")
		return
	}
	cert := domain.Certification{
		UserID:         u.ID,
		SampleTypeID:   req.SampleTypeID,
		SampleTypeName: st.Name,
		IssuedAt:       time.Now(),
		ExpiresAt:      req.ExpiresAt,
	}
	u.Certifications = append(u.Certifications, cert)
	u.Qualifications = append(u.Qualifications, st.Name)
	if err := s.st.UpdateUser(u); err != nil {
		WriteError(w, http.StatusInternalServerError, "internal", "save failed")
		return
	}
	s.audit(caller, "issue_certification", "user", u.ID.String(), true, "success", map[string]any{"sampleType": st.Name})
	s.st.AppendEvent("user.certification_issued", map[string]interface{}{"userId": u.ID.String(), "sampleTypeId": st.ID.String()})
	Created(w, cert)
}

