package api

import (
	"encoding/json"
	"net/http"
	"strings"
	"time"

	"arena.local/lab/internal/domain"

	"github.com/google/uuid"
)

// handleUIBootstrap — GET /api/ui/bootstrap
func (s *Server) handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}
	roleSel := false
	if u.ActiveRole == "" && len(u.Roles) > 0 {
		roleSel = true
	}
	samples := s.st.SamplesByRequester(u.ID)
	ops := s.st.OperationsState()
	OK(w, map[string]any{
		"user": map[string]any{
			"userId":               u.ID,
			"username":             u.Username,
			"fullName":             u.FullName,
			"roles":                u.Roles,
			"activeRole":           u.ActiveRole,
			"roleSelectionRequired": roleSel,
		},
		"serverTime":       time.Now().UTC().Format(time.RFC3339),
		"requesterSamples": samples,
		"operations":       ops,
	})
}

// handleReadSampleState — GET /api/read-sample-state/{sampleId}
func (s *Server) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}
	parts := strings.Split(strings.TrimPrefix(r.URL.Path, "/api/read-sample-state/"), "/")
	if len(parts) == 0 || parts[0] == "" {
		WriteError(w, http.StatusBadRequest, "invalid_id", "sample id required")
		return
	}
	sid, err := uuid.Parse(parts[0])
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_id", "invalid uuid")
		return
	}
	samp, ok := s.st.GetSample(sid)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	OK(w, samp)
}

// handleReadSampleLifecycle — POST /api/read-sample-lifecycle
func (s *Server) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}
	var req struct {
		SampleID uuid.UUID `json:"sampleId"`
	}
	if err := ReadJSON(r, &req); err != nil || req.SampleID == uuid.Nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "sampleId required")
		return
	}
	samp, ok := s.st.GetSample(req.SampleID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	events := s.st.SampleLifecycle(samp.ID)
	OK(w, map[string]any{"sample": samp, "events": events})
}

// handleSetLocationStatus — POST /api/set-location-status
func (s *Server) handleSetLocationStatus(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}
	if !HasRole(u, "administrator", "dispatcher") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin or dispatcher role required")
		return
	}
	var req struct {
		LocationID uuid.UUID `json:"locationId"`
		Active     bool      `json:"active"`
	}
	if err := ReadJSON(r, &req); err != nil || req.LocationID == uuid.Nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "locationId required")
		return
	}
	loc, ok := s.st.GetLocation(req.LocationID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "location not found")
		return
	}
	loc.Active = req.Active
	s.st.UpdateLocation(loc)
	s.audit(u, "set_location_status", "location", loc.ID.String(), true, "ok", map[string]any{"active": req.Active})
	OK(w, loc)
}

// handleSetLocationFunctionStatus — POST /api/set-location-function-status
func (s *Server) handleSetLocationFunctionStatus(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}
	if !HasRole(u, "administrator", "dispatcher") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin or dispatcher role required")
		return
	}
	var req struct {
		LocationID   uuid.UUID `json:"locationId"`
		FunctionType string    `json:"functionType"`
		Active       bool      `json:"active"`
