// handleUIBootstrap — GET /api/ui/bootstrap
func (s *Server) handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}
	roleSel := false
	if u.ActiveRole == "" && len(u.Roles) > 0 {
		roleSel = true
	}
	samples := s.st.SamplesByRequester(u.ID)
	ops := s.st.OperationsState()
	OK(w, map[string]any{
		"user": map[string]any{
			"userId":               u.ID,
			"username":             u.Username,
			"fullName":             u.FullName,
			"roles":                u.Roles,
			"activeRole":           u.ActiveRole,
			"roleSelectionRequired": roleSel,
		},
		"serverTime":       time.Now().UTC().Format(time.RFC3339),
		"requesterSamples": samples,
		"operations":       ops,
	})
}

