			&j.CreatedAt, &j.UpdatedAt); err != nil {
			return err
		}
		json.Unmarshal(samplesJSON, &j.SampleIDs)
		json.Unmarshal(stopsJSON, &j.Stops)
		json.Unmarshal(legsJSON, &j.Legs)
