// ---------- IDEMPOTENCY ----------

func (s *Store) IdempotencyKey(key, method, path string) string {
	h := sha256.Sum256([]byte(method + ":" + path + ":" + key))
	return hex.EncodeToString(h[:])
}

func (s *Store) GetIdempotency(k string) (*domain.IdempotencyRecord, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	r, ok := s.idempotency[k]
	return r, ok
}

func (s *Store) SetIdempotency(r *domain.IdempotencyRecord) {
	s.mu.Lock()
	defer s.mu.Unlock()
	r.CreatedAt = time.Now()
	s.idempotency[r.Key] = r
}

// ---------- SESSIONS ----------

func (s *Store) PutSession(token string, uid uuid.UUID) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.sessions[token] = uid
}

func (s *Store) GetSession(token string) (uuid.UUID, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	u, ok := s.sessions[token]
	return u, ok
}

func (s *Store) DeleteSession(token string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.sessions, token)
}

// ---------- EVENTS ----------

func (s *Store) AppendEvent(evType string, payload map[string]interface{}) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.nextEventID++
	ev := domain.RealtimeEvent{
		ID:        s.nextEventID,
		Type:      evType,
		Timestamp: time.Now(),
		Payload:   payload,
	}
	s.events = append(s.events, ev)
	if len(s.events) > 5000 {
		s.events = s.events[len(s.events)-5000:]
	}
	if s.mongo != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		coll := s.mongo.Database("lab").Collection("realtime_events")
		coll.InsertOne(ctx, bson.M{"id": ev.ID, "type": ev.Type, "timestamp": ev.Timestamp, "payload": ev.Payload})
	}
}

func (s *Store) GetEventsSince(cursor int64) ([]domain.RealtimeEvent, int64) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	out := []domain.RealtimeEvent{}
	maxID := cursor
	for _, ev := range s.events {
		if ev.ID > cursor {
			out = append(out, ev)
			if ev.ID > maxID {
				maxID = ev.ID
			}
		}
	}
	return out, maxID
}

// ---------- DISRUPTIONS ----------

func (s *Store) RecordDisruption(id uuid.UUID, info map[string]interface{}) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.disruptions[id] = info
}

func (s *Store) ListDisruptions() []map[string]interface{} {
	s.mu.RLock()
	defer s.mu.RUnlock()
	out := make([]map[string]interface{}, 0, len(s.disruptions))
	for _, d := range s.disruptions {
		out = append(out, d)
	}
	return out
}

// ---------- AUDIT ----------

func (s *Store) AppendAudit(e domain.AuditEntry) error {
	if s.mongo != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		coll := s.mongo.Database("lab").Collection("audit")
		_, err := coll.InsertOne(ctx, bson.M{
			"id":            e.ID,
			"actorId":       e.ActorID,
			"actorUsername": e.ActorUsername,
			"role":          e.Role,
			"action":        e.Action,
			"entityType":    e.EntityType,
			"entityId":      e.EntityID,
			"outcome":       e.Outcome,
			"success":       e.Success,
			"changes":       e.Changes,
			"timestamp":     e.Timestamp,
		})
		return err
	}
	return nil
}

// helper

func mapToBSON(m map[string]interface{}) bson.M {
	out := bson.M{}
	for k, v := range m {
		out[k] = v
	}
	return out
}

// AllJourneys returns all journeys (alias)
func (s *Store) AllJourneys() []*domain.JourneyPlan { return s.ListJourneys() }
func (s *Store) AllSamples() []*domain.Sample       { return s.ListSamples() }
func (s *Store) AllAssignments() []*domain.Assignment { return s.ListAssignments() }
func (s *Store) AllHandoffs() []*domain.Handoff     { return s.ListHandoffs() }
func (s *Store) AllUsers() []*domain.User           { return s.ListUsers() }
func (s *Store) AllSampleTypes() []*domain.SampleType { return s.ListSampleTypes() }
func (s *Store) AllLocations() []*domain.Location   { return s.ListLocations() }
func (s *Store) AllConnections() []*domain.Connection { return s.ListConnections() }
func (s *Store) MongoHandle() *mongo.Client { return s.mongo }

// ---------- WIPE (for reset) ----------

func (s *Store) Wipe() {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.users = make(map[uuid.UUID]*domain.User)
	s.usersByName = make(map[string]*domain.User)
	s.sampleTypes = make(map[uuid.UUID]*domain.SampleType)
	s.sampleTypesByName = make(map[string]*domain.SampleType)
	s.locations = make(map[uuid.UUID]*domain.Location)
	s.connections = make(map[uuid.UUID]*domain.Connection)
	s.acceptances = make(map[uuid.UUID]*domain.LabAcceptance)
	s.requests = make(map[uuid.UUID]*domain.CollectionRequest)
	s.samples = make(map[uuid.UUID]*domain.Sample)
	s.journeys = make(map[uuid.UUID]*domain.JourneyPlan)
	s.assignments = make(map[uuid.UUID]*domain.Assignment)
	s.handoffs = make(map[uuid.UUID]*domain.Handoff)
	s.reservations = make(map[uuid.UUID]*domain.CapacityReservation)
	s.idempotency = make(map[string]*domain.IdempotencyRecord)
	s.sessions = make(map[string]uuid.UUID)
	s.disruptions = make(map[uuid.UUID]map[string]interface{})
	s.events = nil
	s.nextEventID = 0
}

// ---------- Counts ----------

func (s *Store) Stats() map[string]int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return map[string]int{
		"users":        len(s.users),
		"sampleTypes":  len(s.sampleTypes),
		"locations":    len(s.locations),
		"connections":  len(s.connections),
		"requests":     len(s.requests),
		"samples":      len(s.samples),
		"journeys":     len(s.journeys),
		"assignments":  len(s.assignments),
		"handoffs":     len(s.handoffs),
		"reservations": len(s.reservations),
		"sessions":     len(s.sessions),
		"events":       len(s.events),
	}
}

// Compile-time guards
var _ = fmt.Sprintf
var _ = mapToBSON

