package store

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"sync"
	"time"

	"arena.local/lab/internal/domain"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/redis/go-redis/v9"
	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
)

type Store struct {
	mu      sync.RWMutex
	pg      *pgxpool.Pool
	rdb     *redis.Client
	mongo   *mongo.Client

	// in-memory caches for fast access; durable state in PG
	users          map[uuid.UUID]*domain.User
	usersByName    map[string]*domain.User
	sampleTypes    map[uuid.UUID]*domain.SampleType
	sampleTypesByName map[string]*domain.SampleType
	locations      map[uuid.UUID]*domain.Location
	connections    map[uuid.UUID]*domain.Connection
	acceptances    map[uuid.UUID]*domain.LabAcceptance
	requests       map[uuid.UUID]*domain.CollectionRequest
	samples        map[uuid.UUID]*domain.Sample
	journeys       map[uuid.UUID]*domain.JourneyPlan
	assignments    map[uuid.UUID]*domain.Assignment
	handoffs       map[uuid.UUID]*domain.Handoff
	reservations   map[uuid.UUID]*domain.CapacityReservation
	idempotency    map[string]*domain.IdempotencyRecord
	sessions       map[string]uuid.UUID // token -> userId

	disruptions    map[uuid.UUID]map[string]interface{}
	exceptions     map[uuid.UUID]*domain.Exception
	events         []domain.RealtimeEvent
	nextEventID    int64
}

func New(ctx context.Context, pg *pgxpool.Pool, rdb *redis.Client, m *mongo.Client) *Store {
	s := &Store{
		pg:              pg,
