// ---------- USERS ----------

func (s *Store) CreateUser(u *domain.User) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.usersByName[u.Username]; ok {
		return errors.New("username exists")
	}
	if u.ID == uuid.Nil {
		u.ID = uuid.New()
	}
	if u.Roles == nil {
		u.Roles = []string{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	if u.Certifications == nil {
		u.Certifications = []domain.Certification{}
	}
	if u.ActiveRole == "" && len(u.Roles) > 0 {
		u.ActiveRole = u.Roles[0]
	}
	s.users[u.ID] = u
	s.usersByName[u.Username] = u
	return s.persistUser(u)
}

func (s *Store) GetUser(id uuid.UUID) (*domain.User, bool) {
