// ---------- EVENTS ----------

func (s *Store) AppendEvent(evType string, payload map[string]interface{}) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.nextEventID++
	ev := domain.RealtimeEvent{
		ID:        s.nextEventID,
		Type:      evType,
		Timestamp: time.Now(),
		Payload:   payload,
	}
	s.events = append(s.events, ev)
	if len(s.events) > 5000 {
		s.events = s.events[len(s.events)-5000:]
	}
	if s.mongo != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		coll := s.mongo.Database("lab").Collection("realtime_events")
		coll.InsertOne(ctx, bson.M{"id": ev.ID, "type": ev.Type, "timestamp": ev.Timestamp, "payload": ev.Payload})
	}
}

func (s *Store) GetEventsSince(cursor int64) ([]domain.RealtimeEvent, int64) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	out := []domain.RealtimeEvent{}
	maxID := cursor
	for _, ev := range s.events {
		if ev.ID > cursor {
			out = append(out, ev)
			if ev.ID > maxID {
				maxID = ev.ID
			}
		}
	}
	return out, maxID
}

