)

// handleUIBootstrap — GET /api/ui/bootstrap
func (s *Server) handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}
	roleSel := false
	if u.ActiveRole == "" && len(u.Roles) > 0 {
		roleSel = true
	}
	samples := s.st.SamplesByRequester(u.ID)
	ops := s.st.OperationsState()
	OK(w, map[string]any{
		"user": map[string]any{
			"userId":               u.ID,
			"username":             u.Username,
			"fullName":             u.FullName,
			"roles":                u.Roles,
			"activeRole":           u.ActiveRole,
			"roleSelectionRequired": roleSel,
		},
		"serverTime":       time.Now().UTC().Format(time.RFC3339),
		"requesterSamples": samples,
		"operations":       ops,
	})
}

// handleReadSampleState — GET /api/read-sample-state/{sampleId}
func (s *Server) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}
	parts := strings.Split(strings.TrimPrefix(r.URL.Path, "/api/read-sample-state/"), "/")
	if len(parts) == 0 || parts[0] == "" {
		WriteError(w, http.StatusBadRequest, "invalid_id", "sample id required")
		return
	}
	sid, err := uuid.Parse(parts[0])
	if err != nil {
		WriteError(w, http.StatusBadRequest, "invalid_id", "invalid uuid")
		return
	}
	samp, ok := s.st.GetSample(sid)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	OK(w, samp)
}

