	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}
	if !HasAnyRole(u, "administrator", "dispatcher") {
		WriteError(w, http.StatusForbidden, "forbidden", "admin or dispatcher role required")
		return
	}
	var req struct {
		LocationID   uuid.UUID `json:"locationId"`
		FunctionType string    `json:"functionType"`
		Active       bool      `json:"active"`
	}
	if err := ReadJSON(r, &req); err != nil || req.LocationID == uuid.Nil || req.FunctionType == "" {
		WriteError(w, http.StatusBadRequest, "invalid_json", "locationId and functionType required")
		return
	}
	loc, ok := s.st.GetLocation(req.LocationID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "location not found")
		return
	}
	if req.FunctionType == "collection_point" {
		loc.Functions.CollectionPoint = req.Active
	} else if req.FunctionType == "transfer_point" {
		loc.Functions.TransferPoint = req.Active
	} else if req.FunctionType == "hub" {
		loc.Functions.Hub = req.Active
	} else if req.FunctionType == "laboratory" {
		loc.Functions.Laboratory = req.Active
	} else {
		WriteError(w, http.StatusBadRequest, "invalid_function", "unknown functionType")
		return
	}
	s.st.UpdateLocation(loc)
	s.audit(u, "set_location_function_status", "location", loc.ID.String(), true, "ok", map[string]any{"function": req.FunctionType, "active": req.Active})
	OK(w, loc)
