		return
	}
	if req.IdempotencyKey == "" {
		WriteError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if existing, ok := s.st.GetIdempotent(req.IdempotencyKey, r.URL.Path); ok {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(existing.Status)
		w.Write([]byte(existing.Response))
