		WriteError(w, http.StatusBadRequest, "invalid_json", "locationId and functionType required")
		return
	}
	loc, ok := s.st.GetLocation(req.LocationID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "location not found")
		return
