		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}
	if !HasAnyRole(u, "administrator", "dispatcher", "requester") {
		WriteError(w, http.StatusForbidden, "forbidden", "role required")
		return
	}
	var req struct {
		JourneyID      uuid.UUID `json:"journeyId"`
		IdempotencyKey string    `json:"idempotencyKey"`
		Reason         string    `json:"reason"`
	}
	if err := ReadJSON(r, &req); err != nil || req.JourneyID == uuid.Nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "journeyId required")
		return
	}
	if req.IdempotencyKey == "" {
		WriteError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if existing, ok := s.st.GetIdempotency(s.st.IdempotencyKey(req.IdempotencyKey, r.Method, r.URL.Path)); ok {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(existing.Status)
