// handleCancelJourney — POST /api/cancel-journey
func (s *Server) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}
	if !HasAnyRole(u, "administrator", "dispatcher", "requester") {
		WriteError(w, http.StatusForbidden, "forbidden", "role required")
		return
	}
	var req struct {
		JourneyID      uuid.UUID `json:"journeyId"`
		IdempotencyKey string    `json:"idempotencyKey"`
		Reason         string    `json:"reason"`
	}
	if err := ReadJSON(r, &req); err != nil || req.JourneyID == uuid.Nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "journeyId required")
		return
	}
	if req.IdempotencyKey == "" {
		WriteError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if existing, ok := s.st.GetIdempotency(s.st.IdempotencyKey(req.IdempotencyKey, r.Method, r.URL.Path)); ok {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(existing.Status)
		w.Write([]byte(existing.Response))
		return
	}
	j, ok := s.st.GetJourney(req.JourneyID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	j.Status = "cancelled"
	s.st.UpdateJourney(j)
	sampleIDs := append([]uuid.UUID{}, j.SampleIDs...)
	resp := map[string]any{
		"journeyId":  j.ID,
		"status":     "cancelled",
		"sampleIds":  sampleIDs,
	}
	s.audit(u, "cancel_journey", "journey", j.ID.String(), true, "ok", map[string]any{"reason": req.Reason})
	body, _ := json.Marshal(map[string]any{"data": resp})
	s.st.SetIdempotency(&domain.IdempotencyRecord{
		Key: s.st.IdempotencyKey(req.IdempotencyKey, r.Method, r.URL.Path),
		Method: r.Method, Path: r.URL.Path,
		Status: http.StatusCreated, Response: string(body),
	})
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	w.Write(body)
}

