		WriteError(w, http.StatusBadRequest, "invalid_json", "journeyId required")
		return
	}
	if req.IdempotencyKey == "" {
		WriteError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	if existing, ok := s.st.GetIdempotency(s.st.IdempotencyKey(req.IdempotencyKey, r.Method, r.URL.Path)); ok {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(existing.Status)
		w.Write([]byte(existing.Response))
		return
	}
	j, ok := s.st.GetJourney(req.JourneyID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	j.Status = "cancelled"
	s.st.UpdateJourney(j)
	sampleIDs := append([]uuid.UUID{}, j.SampleIDs...)
	resp := map[string]any{
		"journeyId":  j.ID,
		"status":     "cancelled",
		"sampleIds":  sampleIDs,
	}
