	s.st.SetIdempotency(&domain.IdempotencyRecord{
		Key: s.st.IdempotencyKey(req.IdempotencyKey, r.Method, r.URL.Path),
		Method: r.Method, Path: r.URL.Path,
		Status: http.StatusCreated, Response: string(body),
	})
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	w.Write(body)
}

