func (s *Server) handleRecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		WriteError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
		return
	}
	u := currentUser(r)
	if u == nil {
		WriteError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}
	if !HasAnyRole(u, "laboratory_intake_operator", "administrator", "dispatcher") {
		WriteError(w, http.StatusForbidden, "forbidden", "lab role required")
		return
	}
	var req struct {
		SampleID    uuid.UUID `json:"sampleId"`
		ExceptionID uuid.UUID `json:"exceptionId"`
		Reason      string    `json:"reason"`
		Notes       string    `json:"notes"`
	}
	if err := ReadJSON(r, &req); err != nil || req.SampleID == uuid.Nil {
		WriteError(w, http.StatusBadRequest, "invalid_json", "sampleId required")
		return
	}
	samp, ok := s.st.GetSample(req.SampleID)
	if !ok {
		WriteError(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	exc := domain.Exception{
		ID:        uuid.New(),
		SampleID:  samp.ID,
		ActorID:   u.ID,
		Reason:    req.Reason,
		Notes:     req.Notes,
		CreatedAt: time.Now().UTC(),
	}
	s.st.AppendException(exc)
	s.audit(u, "record_laboratory_exception", "sample", samp.ID.String(), true, "ok", map[string]any{"reason": req.Reason})
	Created(w, exc)
}

